import{_ as t,o,c as r,a2 as a}from"./chunks/framework.DdtnLau3.js";const u=JSON.parse('{"title":"Your first Work","description":"","frontmatter":{},"headers":[],"relativePath":"guide/first-work.md","filePath":"guide/first-work.md"}'),n={name:"guide/first-work.md"};function i(s,e,l,d,p,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="your-first-work" tabindex="-1">Your first Work <a class="header-anchor" href="#your-first-work" aria-label="Permalink to &quot;Your first Work&quot;">​</a></h1><p>Follow <a href="/piwork/guide/quick-start.html">Quick Start</a> and complete browser setup. After preparation completes, the workbench opens automatically; <strong>Open workbench</strong> is also available. Choose <strong>New Work</strong>, then send a message in Chat. Use Files for the workspace, Settings to save and explicitly Apply configuration, and Service to preview or open an application tab. Closing the browser does not stop a Work.</p><p>Service response Cookies stay in server-side partitions. Apps relying on script-read/written Cookies are outside transparent support. Script-written browser Cookies may be shared across Services on the same IP and are never adopted by the proxy. See Installation for details.</p><h2 id="create-and-use-a-work" tabindex="-1">Create and use a Work <a class="header-anchor" href="#create-and-use-a-work" aria-label="Permalink to &quot;Create and use a Work&quot;">​</a></h2><ol><li>In Quick setup, choose or add a model and select <strong>Save and continue</strong>. Model saving, Runtime binding and preparation have separate feedback. Test is optional; saving does not call the model.</li><li>Preparation shows the actual components still being awaited. The completion <strong>Open workbench</strong> action requires every dependency to be Ready; the Admin topbar also lets you return while preparation continues.</li><li>Select <strong>New Work</strong>, enter a name and create it. Open the Work after readiness, then describe your task in Chat.</li><li>Use Files for workspace content and Service entries for running applications. Default model changes affect future Works; an existing Work requires its owner&#39;s explicit configuration save and Apply.</li></ol><h2 id="share-and-continue" tabindex="-1">Share and continue <a class="header-anchor" href="#share-and-continue" aria-label="Permalink to &quot;Share and continue&quot;">​</a></h2><p>Stop the Work before exporting its <code>.work</code> package from the Work actions. Import on another installation creates a stopped Work; check the destination model and environment, then explicitly <strong>Start</strong> it. Import does not replay history. Closing the browser does not stop a running Work.</p>',7)])])}const k=t(n,[["render",i]]);export{u as __pageData,k as default};
